# --------------------------------------------------------------------------
# Agentic OS view (/os). A second face over the SAME sources as the status
# page, plus four scans the status page does not need. Everything here obeys
# the rules in DESIGN.md: standard library only, read-only, fresh per request,
# never raises. A source that breaks degrades to an empty list, never a 500.
#
# This view is READ-ONLY BY DESIGN. It shows which model and effort each skill
# would run at and when each routine next fires; it cannot run or change
# either. DESIGN.md deliberately left buttons out, and adding a write path to
# a page any local tab can reach is a separate decision with its own guard
# (~/.claude/scripts/skill-button.sh exists for that day).
# --------------------------------------------------------------------------

SKILLS_DIR = HOME / '.claude/skills'
VAULT = HOME / 'SecondBrain'
LAUNCH_AGENTS = HOME / 'Library/LaunchAgents'

# Directory names that never hold a deliverable worth ringing.
RING_PRUNE = {
    '.git', 'node_modules', '__pycache__', '.venv', 'venv', 'graphify-out',
    '.playwright-mcp', 'frames', '.pytest_cache', 'site-packages', '.next',
    'dist', 'build', '.mypy_cache', '.ruff_cache',
}
RING_EXT = {'.html', '.pdf'}

# Identifiable athlete data. SENSITIVE_PATHS is the health-data exclusion that
# CLAUDE.md mandates and that gf_gemini.py also enforces. RING_EXCLUDE is
# broader and applies to THIS VIEW ONLY: S2 Cognition reports carry athlete
# names in their filenames, and the ring renders filenames as labels, so a
# glance at this page would put named cognitive results on screen. The files
# stay readable everywhere else on the machine — they are just not ambient.
# Remove an entry here if you want it back on the ring.
RING_EXCLUDE = ('COG_S2_Position_Reports',)

RING_MAX = 40
RING_PER_DIR = 2        # stops one generated batch from eating the whole ring
RING_PER_PROJECT = 6


def _short_age(secs: float) -> str:
    """Compact age for a ring badge: 4H, 6D, 3W. '' under an hour."""
    if secs < 3600:
        return ''
    if secs < 172800:
        return f'{int(secs / 3600)}H'
    if secs < 1209600:
        return f'{int(secs / 86400)}D'
    return f'{int(secs / 604800)}W'


def _ring_candidates():
    """Every ringable artifact under ~/DEV, newest first. Never raises."""
    out = []
    try:
        for root, dirs, files in os.walk(DEV):
            try:
                depth = len(Path(root).relative_to(DEV).parts)
            except ValueError:
                dirs[:] = []
                continue
            if depth >= 4:
                dirs[:] = []
            dirs[:] = [d for d in dirs
                       if d not in RING_PRUNE and not d.startswith('.')]
            if any(s in root for s in SENSITIVE_PATHS + RING_EXCLUDE):
                dirs[:] = []
                continue
            for f in files:
                if Path(f).suffix.lower() not in RING_EXT:
                    continue
                p = Path(root) / f
                try:
                    out.append((p.stat().st_mtime, p))
                except OSError:
                    pass
    except Exception:                                         # noqa: BLE001
        return []
    out.sort(key=lambda t: t[0], reverse=True)
    return out


def ring_paths():
    """The exact Paths currently on the ring.

    /open allowlists these BY IDENTICAL STRING, recomputed at click time, the
    same way it allowlists LINKS. The set moves as files are written, so a
    click can 404 if the ring shifted under it — that is the correct failure.
    Widening this to a prefix or subtree check is how a traversal gets in.
    """
    return [p for _, p in _ring_artifacts()]


def _ring_artifacts():
    """Top RING_MAX artifacts, capped per folder and per project.

    Uncapped 'most recent' is not 'what did I just make': one scheduled job
    that rewrites 20 dashboards at 06:34 takes the whole ring and buries every
    real deliverable. The caps keep the spread across projects.
    """
    dirc, projc, picked = {}, {}, []
    for mtime, p in _ring_candidates():
        d = str(p.parent)
        try:
            proj = p.relative_to(DEV).parts[0]
        except (ValueError, IndexError):
            continue
        if dirc.get(d, 0) >= RING_PER_DIR:
            continue
        if projc.get(proj, 0) >= RING_PER_PROJECT:
            continue
        dirc[d] = dirc.get(d, 0) + 1
        projc[proj] = projc.get(proj, 0) + 1
        picked.append((mtime, p))
        if len(picked) >= RING_MAX:
            break
    return picked


def src_artifacts():
    """Ring rows. Only files /open will actually serve are offered."""
    rows, total = [], len(_ring_candidates())
    now = time.time()
    for mtime, p in _ring_artifacts():
        if not safe_regular_file(p):
            continue                    # never offer a link /open would refuse
        try:
            rel = str(p.relative_to(DEV))
        except ValueError:
            continue
        rows.append({
            'label': p.stem.replace('_', ' ').replace('-', ' ')[:46],
            'project': rel.split('/')[0],
            'rel': rel,
            'path': str(p),
            'kind': p.suffix.lower().lstrip('.'),
            'age': _short_age(now - mtime),
            'when': time.strftime('%-d %b', time.localtime(mtime)),
        })
    return {'total': total, 'shown': len(rows), 'rows': rows}


def src_skills():
    """Name + description from every ~/.claude/skills/*/SKILL.md frontmatter."""
    rows = []
    try:
        dirs = sorted(d for d in SKILLS_DIR.iterdir() if d.is_dir())
    except OSError:
        return {'total': 0, 'rows': []}
    for d in dirs:
        f = d / 'SKILL.md'
        try:
            head = f.read_text(errors='replace')[:4000]
        except OSError:
            continue
        if not head.startswith('---'):
            continue
        block = head.split('---', 2)[1] if head.count('---') >= 2 else ''
        name, desc = d.name, ''
        for line in block.splitlines():
            if line.startswith('name:'):
                name = line[5:].strip() or d.name
            elif line.startswith('description:'):
                desc = line[12:].strip()
        rows.append({'name': name, 'desc': desc[:240], 'dir': d.name})
    return {'total': len(rows), 'rows': rows}


def _next_fire(entries, now):
    """Soonest future datetime for a StartCalendarInterval, or None.

    launchd semantics: an absent key means 'every value'. Weekday 0 and 7 both
    mean Sunday. Scans 8 days so a weekly job is always found.
    """
    best = None
    for e in entries:
        for ahead in range(8):
            day = now + timedelta(days=ahead)
            wd = e.get('Weekday')
            if wd is not None and (wd % 7) != (day.isoweekday() % 7):
                continue
            if e.get('Day') is not None and e['Day'] != day.day:
                continue
            if e.get('Month') is not None and e['Month'] != day.month:
                continue
            hh = e.get('Hour')
            mm = e.get('Minute')
            cands = [hh] if hh is not None else range(24)
            for h in cands:
                m = mm if mm is not None else 0
                when = day.replace(hour=h, minute=m, second=0, microsecond=0)
                if when > now and (best is None or when < best):
                    best = when
            if best is not None and ahead > 0:
                break
    return best


def src_routines():
    """Scheduled work, from the plists, judged against live launchctl state.

    DESIGN.md rule kept: launchctl is the truth for up/exit. The plist supplies
    the SCHEDULE only — it can never claim a job succeeded.
    """
    live = {}
    try:
        out = subprocess.run(['launchctl', 'list'], capture_output=True,
                             text=True, timeout=10).stdout
        for line in out.splitlines():
            parts = line.split('\t')
            if len(parts) >= 3 and parts[2].startswith('com.keystone.'):
                live[parts[2].replace('com.keystone.', '')] = (parts[0], parts[1])
    except Exception:                                         # noqa: BLE001
        pass

    now = datetime.now()
    rows = []
    try:
        plists = sorted(LAUNCH_AGENTS.glob('com.keystone.*.plist'))
    except OSError:
        plists = []
    for f in plists:
        try:
            with open(f, 'rb') as fh:
                d = plistlib.load(fh)
        except Exception:                                     # noqa: BLE001
            continue
        name = str(d.get('Label', f.stem)).replace('com.keystone.', '')
        pid, code = live.get(name, ('-', '-'))
        running = pid.isdigit() and pid != '0'

        sci = d.get('StartCalendarInterval')
        interval = d.get('StartInterval')
        nxt = None
        if sci is not None:
            entries = sci if isinstance(sci, list) else [sci]
            nxt = _next_fire(entries, now)
            label = nxt.strftime('%H:%M') if nxt else '--:--'
        elif interval:
            label = f'~{int(interval / 3600)}h' if interval >= 3600 else f'~{interval}s'
        elif d.get('KeepAlive'):
            label = 'always'
        else:
            label = '--:--'

        if running:
            status = 'UP'
        elif sci is not None and nxt is not None and (nxt - now) <= timedelta(hours=6):
            status = 'NEXT'
        elif sci is not None or interval:
            status = 'QUEUED'
        else:
            status = 'IDLE'
        rows.append({
            'time': label, 'name': name, 'status': status,
            'pid': pid if running else '', 'exit': code,
            'nextIso': nxt.isoformat() if nxt else '',
        })

    # One NEXT only: the soonest calendar job. Everything else is QUEUED.
    soon = [r for r in rows if r['status'] == 'NEXT']
    if soon:
        soon.sort(key=lambda r: r['nextIso'])
        for r in soon[1:]:
            r['status'] = 'QUEUED'
    rows.sort(key=lambda r: (r['status'] != 'NEXT', r['time']))
    up = sum(1 for r in rows if r['status'] == 'UP')
    return {'total': len(rows), 'up': up, 'rows': rows}


def src_vault():
    """SecondBrain shape: note count per top-level folder. Never reads bodies."""
    folders, total = [], 0
    try:
        for d in sorted(VAULT.iterdir()):
            if not d.is_dir() or d.name.startswith('.'):
                continue
            n = sum(1 for _ in d.rglob('*.md'))
            total += n
            if n:
                folders.append({'name': d.name, 'notes': n})
    except OSError:
        return {'notes': 0, 'folders': []}
    total += sum(1 for f in VAULT.glob('*.md'))
    folders.sort(key=lambda f: f['notes'], reverse=True)
    return {'notes': total, 'folders': folders[:8]}


def src_microapps():
    """The existing LINKS allowlist, with liveness. Same set /open serves."""
    rows = []
    for label, p in LINKS:
        ok = safe_regular_file(p)
        rows.append({'name': label, 'path': str(p), 'ok': ok,
                     'age': _age(p) if ok else 'missing',
                     'kind': p.suffix.lower().lstrip('.')})
    return rows


def api_state():
    """Everything /os renders, as one JSON-safe dict. Never raises."""
    def safe(fn, fallback):
        try:
            return fn()
        except Exception as exc:                              # noqa: BLE001
            return fallback(exc) if callable(fallback) else fallback

    health = []
    for label, fn in (('Agents', src_agents), ('Backup', src_backup),
                      ('Graph', src_graph), ('Failures', src_errors),
                      ('Projects', src_projects), ('Ledger', src_ledger)):
        try:
            state, head, detail = fn()
        except Exception as exc:                              # noqa: BLE001
            state, head, detail = UNKNOWN, f'{label} unreadable', [repr(exc)[:120]]
        health.append({'name': label, 'state': state, 'head': head,
                       'detail': list(detail)[:12]})
    worst = UNKNOWN
    for rank in (BAD, WARN, OK):
        if any(h['state'] == rank for h in health):
            worst = rank
            break

    return {
        'generated': datetime.now().isoformat(timespec='seconds'),
        'generatedUtc': datetime.now(timezone.utc).isoformat(timespec='seconds'),
        'readOnly': True,
        'brand': {'name': 'KEYSTONE', 'accent': 'Agentic OS',
                  'byline': 'Eric Rash | Applied Performance · Baylor Athletics'},
        'health': {'state': worst, 'rows': health},
        'routines': safe(src_routines, {'total': 0, 'up': 0, 'rows': []}),
        'skills': safe(src_skills, {'total': 0, 'rows': []}),
        'artifacts': safe(src_artifacts, {'total': 0, 'shown': 0, 'rows': []}),
        'vault': safe(src_vault, {'notes': 0, 'folders': []}),
        'microapps': safe(src_microapps, []),
    }

